// swift-tools-version: 6.0
import PackageDescription

// `Shared` wraps the UniFFI bindings of figlock-ffi for the app and the AutoFill extension. The static library
// (`FigLockFFI.xcframework`) and the Swift bindings (`Sources/FigLockFFI/figlock_ffi.swift`) are generated by
// `just ios-xcframework` and are not committed, so they always match the Rust core they were built from.
let package = Package(
    name: "Shared",
    platforms: [.iOS(.v18)],
    products: [
        .library(name: "Shared", targets: ["Shared"])
    ],
    targets: [
        .binaryTarget(name: "figlock_ffiFFI", path: "Frameworks/FigLockFFI.xcframework"),
        .target(
            name: "FigLockFFI",
            dependencies: ["figlock_ffiFFI"],
            // The generated file is Swift 5 code; keep the language mode of this one target at 5.
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
        .target(name: "Shared", dependencies: ["FigLockFFI"]),
        .testTarget(name: "SharedTests", dependencies: ["Shared"]),
    ]
)
